// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(keccak256("test"));

        // The reference contract stores the guess and sets block number; the bug reverts.
        // We verify that the block number is non-zero (reference) vs zero (bug) — but the bug reverts,
        // so the call would not complete. We wrap the call to capture revert.
        bool success;
        bytes32 hash = keccak256("test");
        vm.prank(user);
        try c.lockInGuess{value: 1 ether}(hash) {
            success = true;
        } catch {
            success = false;
        }
        // In reference, the second call reverts because user already has a guess (block != 0).
        // In bug, the first call already reverted so user has no guess, second call succeeds.
        // So assert that the reference gives false (second call reverts), bug gives true.
        // We actually want reference: false (revert) and bug: true (accepts 1 ether).
        assertTrue(success == false);
    }
}

