pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x123);
        vm.deal(user, 1 ether);
        vm.deal(address(c), 1 ether);

        // user tries to lock in guess with 0 ether (instead of 1 ether)
        vm.prank(user);
        bool ok;
        try c.lockInGuess{value: 0 ether}(keccak256("test")) { ok = true; }
        catch { ok = false; }

        // In reference: revert => ok = false, user's guess not stored => guesses[user].block == 0
        // In buggy: ok = true, user's guess stored => guesses[user].block != 0
        // But block is private, so we can't read it directly. 
        // Instead check whether the address can proceed to settle:
        // If guess stored, settle() may succeed (with correct answer) or revert.
        // We'll warp past block number and try settle.
        vm.roll(block.number + 2);
        vm.prank(user);
        bool settleOk;
        try c.settle() { settleOk = true; }
        catch { settleOk = false; }

        // Reference: lockInGuess reverted, so guess not stored => settle reverts (require(guesses[msg.sender].block != 0) fails) => settleOk = false
        // Buggy: lockInGuess accepted, guess stored => settle can proceed (maybe revert if guess != answer, but that's not the point) => settleOk could be true or false
        // However, we need a definitive difference.
        // Better approach: use a second user who does nothing.
        // Actually, the simplest: after lockInGuess attempt, if it succeeded the mapping changed; if it reverted, mapping unchanged.
        // Since we can't read mapping directly, let's use a different strategy: 
        // Deploy a helper contract? No, not allowed.
        // Let's use vm.deal to check balance changes? No.
        // The only observable difference is that lockInGuess itself reverts or not.
        // So we assert on the revert boolean for lockInGuess.
        // Re-reference: lockInGuess reverts => ok = false; buggy: ok = true.
        assertTrue(ok == false, "Reference reverts on zero msg.value");
    }
}

